523	
524	
525	    std::set<String> inactive_replicas;
526	    for (const String & replica : replicas)
527	    {
528	        LOG_DEBUG(log, "Waiting for {} to apply mutation {}", replica, mutation_id);
529	        zkutil::EventPtr wait_event = std::make_shared<Poco::Event>();
530	
531	        while (!partial_shutdown_called)
532	        {
533	            /// Mutation maybe killed or whole replica was deleted.
534	            /// Wait event will unblock at this moment.
