539	            }
540	
541	            auto zookeeper = getZooKeeper();
542	            /// Replica could be inactive.
543	            if (!zookeeper->exists(fs::path(zookeeper_path) / "replicas" / replica / "is_active"))
544	            {
545	                LOG_WARNING(log, "Replica {} is not active during mutation. Mutation will be done asynchronously when replica becomes active.", replica);
546	
547	                inactive_replicas.emplace(replica);
548	                break;
549	            }
550	
551	            String mutation_pointer = fs::path(zookeeper_path) / "replicas" / replica / "mutation_pointer";
552	            std::string mutation_pointer_value;
553	            /// Replica could be removed
554	            if (!zookeeper->tryGet(mutation_pointer, mutation_pointer_value, nullptr, wait_event))
555	            {
556	                LOG_WARNING(log, "Replica {} was removed", replica);
557	                break;
558	            }
559	            else if (mutation_pointer_value >= mutation_id) /// Maybe we already processed more fresh mutation
560	                break;                                      /// (numbers like 0000000000 and 0000000001)
561	
562	            /// Replica can become inactive, so wait with timeout and recheck it
563	            if (wait_event->tryWait(1000))
564	                continue;
565	
566	            /// Here we check mutation for errors on local replica. If they happen on this replica
567	            /// they will happen on each replica, so we can check only in-memory info.
