569	            /// If mutation status is empty, than local replica may just not loaded it into memory.
570	            if (mutation_status && !mutation_status->latest_fail_reason.empty())
571	                break;
572	        }
573	
574	        /// This replica inactive, don't check anything
575	        if (!inactive_replicas.empty() && inactive_replicas.contains(replica))
576	            break;
577	
578	        /// It maybe already removed from zk, but local in-memory mutations
