40	void DiskWebServer::initialize(const String & uri_path) const
41	{
42	    std::vector<String> directories_to_load;
43	    LOG_TRACE(log, "Loading metadata for directory: {}", uri_path);
44	    try
45	    {
46	        Poco::Net::HTTPBasicCredentials credentials{};
47	        ReadWriteBufferFromHTTP metadata_buf(Poco::URI(fs::path(uri_path) / ".index"),
48	                                            Poco::Net::HTTPRequest::HTTP_GET,
49	                                            ReadWriteBufferFromHTTP::OutStreamCallback(),
50	                                            ConnectionTimeouts::getHTTPTimeouts(getContext()),
51	                                            credentials);
52	        String file_name;
53	        FileData file_data{};
54	
55	        String dir_name = fs::path(uri_path.substr(url.size())) / "";
56	        LOG_TRACE(&Poco::Logger::get("DiskWeb"), "Adding directory: {}", dir_name);
57	
58	        while (!metadata_buf.eof())
59	        {
60	            readText(file_name, metadata_buf);
61	            assertChar('\t', metadata_buf);
62	
63	            bool is_directory;
64	            readBoolText(is_directory, metadata_buf);
65	            if (!is_directory)
66	            {
67	                assertChar('\t', metadata_buf);
68	                readIntText(file_data.size, metadata_buf);
69	            }
70	            assertChar('\n', metadata_buf);
71	
72	            file_data.type = is_directory ? FileType::Directory : FileType::File;
73	            String file_path = fs::path(uri_path) / file_name;
74	            if (file_data.type == FileType::Directory)
75	            {
76	                directories_to_load.push_back(file_path);
77	                // file_path = fs::path(file_path) / "";
78	            }
79	
80	            file_path = file_path.substr(url.size());
81	            files.emplace(std::make_pair(file_path, file_data));
82	            LOG_TRACE(&Poco::Logger::get("DiskWeb"), "Adding file: {}, size: {}", file_path, file_data.size);
83	        }
84	
85	        files.emplace(std::make_pair(dir_name, FileData({ .type = FileType::Directory })));
86	    }
87	    catch (Exception & e)
88	    {
89	        e.addMessage("while loading disk metadata");
90	        throw;
91	    }
92	
93	    for (const auto & directory_path : directories_to_load)
94	        initialize(directory_path);
95	}
