184	void ReadBufferFromRemoteFSGather::initialize()
185	{
186	    /// One clickhouse file can be split into multiple files in remote fs.
187	    auto current_buf_offset = file_offset_of_buffer_end;
188	    for (size_t i = 0; i < blobs_to_read.size(); ++i)
189	    {
190	        const auto & object = blobs_to_read[i];
191	
192	        if (object.bytes_size > current_buf_offset)
193	        {
194	            /// Do not create a new buffer if we already have what we need.
195	            if (!current_buf || current_buf_idx != i)
196	            {
197	                current_buf_idx = i;
198	                current_buf = createImplementationBuffer(object.absolute_path, object.bytes_size);
199	            }
200	
201	            current_buf->seek(current_buf_offset, SEEK_SET);
202	            return;
203	        }
204	
205	        current_buf_offset -= object.bytes_size;
206	    }
207	    current_buf_idx = blobs_to_read.size();
208	    current_buf = nullptr;
209	}
