212	bool ReadBufferFromRemoteFSGather::nextImpl()
213	{
214	    /// Find first available buffer that fits to given offset.
215	    if (!current_buf)
216	        initialize();
217	
218	    /// If current buffer has remaining data - use it.
219	    if (current_buf)
220	    {
221	        if (readImpl())
222	            return true;
223	    }
224	    else
225	    {
226	        return false;
227	    }
228	
229	    if (!moveToNextBuffer())
230	    {
231	        return false;
232	    }
233	
234	    return readImpl();
235	}
