238	bool ReadBufferFromRemoteFSGather::moveToNextBuffer()
239	{
240	    /// If there is no available buffers - nothing to read.
241	    if (current_buf_idx + 1 >= blobs_to_read.size())
242	        return false;
243	
244	    ++current_buf_idx;
245	
246	    const auto & object = blobs_to_read[current_buf_idx];
247	    current_buf = createImplementationBuffer(object.absolute_path, object.bytes_size);
248	
249	    return true;
