253	bool ReadBufferFromRemoteFSGather::readImpl()
254	{
255	    swap(*current_buf);
256	
257	    bool result = false;
258	
259	    /**
260	     * Lazy seek is performed here.
261	     * In asynchronous buffer when seeking to offset in range [pos, pos + min_bytes_for_seek]
262	     * we save how many bytes need to be ignored (new_offset - position() bytes).
263	     */
264	    if (bytes_to_ignore)
265	    {
266	        total_bytes_read_from_current_file += bytes_to_ignore;
267	        current_buf->ignore(bytes_to_ignore);
268	        result = current_buf->hasPendingData();
269	        file_offset_of_buffer_end += bytes_to_ignore;
270	        bytes_to_ignore = 0;
271	    }
272	
273	    if (!result)
274	        result = current_buf->next();
275	
276	    if (blobs_to_read.size() == 1)
277	    {
278	        file_offset_of_buffer_end = current_buf->getFileOffsetOfBufferEnd();
279	    }
280	    else
281	    {
282	        /// For log family engines there are multiple s3 files for the same clickhouse file
283	        file_offset_of_buffer_end += current_buf->available();
284	    }
